def __contains__(self, sku: object) -> bool:
        """Return True if ``sku`` normalises to a SKU present in the on-hand mapping.

        Non-string inputs or malformed SKUs return False rather than raising.
        """
        if not isinstance(sku, str):
            return False
        try:
            norm = normalize_sku(sku)
        except ValueError:
            return False
        return norm in self._on_hand
